using System;
using System.IO;
using System.Linq;
using System.Runtime.Serialization.Json;
using MediaBrowser.Controller.Library;
using Emby.UserData.Models;

namespace Emby.UserData.Services {
 public sealed class UserDataStore {
  private static readonly object Sync = new object(); private readonly string file;
  public UserDataStore() : this(Plugin.Instance.DataFolderPath) { }
  public UserDataStore(string dataFolderPath) { var folder=Path.Combine(dataFolderPath, "user-data"); Directory.CreateDirectory(folder); file=Path.Combine(folder,"store.json"); }
  public StoreDocument Read() { lock(Sync) { if(!File.Exists(file)) return new StoreDocument(); try { using(var stream=File.OpenRead(file)) return (StoreDocument)new DataContractJsonSerializer(typeof(StoreDocument)).ReadObject(stream) ?? new StoreDocument(); } catch { var corrupt=file+".corrupt-"+DateTime.UtcNow.Ticks; File.Move(file,corrupt); return new StoreDocument(); } } }
  public void Save(StoreDocument data) { lock(Sync) { var tmp=file+".tmp"; using(var stream=File.Create(tmp)) new DataContractJsonSerializer(typeof(StoreDocument)).WriteObject(stream,data); if(File.Exists(file)) File.Replace(tmp,file,null); else File.Move(tmp,file); } }
  public FieldDefinition Upsert(FieldDefinition field) { var d=Read(); var existing=d.Fields.FirstOrDefault(x=>x.Id==field.Id); if(existing==null) { field.Id=string.IsNullOrWhiteSpace(field.Id)?Guid.NewGuid().ToString("N"):field.Id; field.Order=d.Fields.Count; d.Fields.Add(field); } else { existing.Name=field.Name; existing.Type=field.Type; existing.Required=field.Required; existing.IsActive=field.IsActive; existing.Options=field.Options??existing.Options; existing.DisableUserOnDate=field.DisableUserOnDate; existing.ControlsAccess=field.ControlsAccess; existing.AccessAction=field.AccessAction; existing.DefaultBooleanValue=field.DefaultBooleanValue; } if(field.DisableUserOnDate) foreach(var other in d.Fields.Where(x=>x.Id!=field.Id)) other.DisableUserOnDate=false; if(field.ControlsAccess) foreach(var other in d.Fields.Where(x=>x.Id!=field.Id)) other.ControlsAccess=false; Save(d); return field; }
  public FieldDefinition AddSeparator() { var d=Read(); var separator=new FieldDefinition { Name="Nueva fila", IsSeparator=true, IsActive=false, Order=d.Fields.Count }; d.Fields.Add(separator); Save(d); return separator; }
  public void Deactivate(string id) { var d=Read(); var f=d.Fields.FirstOrDefault(x=>x.Id==id); if(f==null) throw new ArgumentException("Field not found"); f.IsActive=false; Save(d); }
  public void Delete(string id) { var d=Read(); d.Fields.RemoveAll(x=>x.Id==id); foreach(var r in d.Users.Values) r.Values.Remove(id); Save(d); }
  public UserRecord GetUser(string id) { var d=Read(); return d.Users.ContainsKey(id)?d.Users[id]:new UserRecord{UserId=id}; }
  public void SaveUser(string id, System.Collections.Generic.Dictionary<string,string> values) { var d=Read(); var active=d.Fields.Where(x=>x.IsActive&&!x.IsSeparator).ToDictionary(x=>x.Id); foreach(var p in values) { if(!active.ContainsKey(p.Key)) throw new ArgumentException("Unknown or inactive field"); Validate(active[p.Key],p.Value); } var existing=d.Users.ContainsKey(id) ? d.Users[id] : new UserRecord { UserId=id }; foreach(var field in active.Keys) { if(values.ContainsKey(field)) existing.Values[field]=values[field]; else existing.Values.Remove(field); } d.Users[id]=existing; Save(d); }
  public void ApplyBooleanAccess(IUserManager userManager,string userId,System.Collections.Generic.Dictionary<string,string> values) { var d=Read(); var field=d.Fields.FirstOrDefault(x=>x.ControlsAccess&&x.Type==FieldType.Boolean); if(field==null||!values.ContainsKey(field.Id)) return; var active=values[field.Id]=="true"; var disable=field.AccessAction=="Disable" ? active : !active; SetUserDisabled(userManager,userId,disable,d); Save(d); }
  private static void SetUserDisabled(IUserManager manager,string id,bool disabled,StoreDocument d) { Guid guid; if(!Guid.TryParse(id,out guid)) return; var get=manager.GetType().GetMethod("GetUserById",new[] { typeof(Guid) }); var user=get.Invoke(manager,new object[] { guid }); if(user==null) return; var policy=user.GetType().GetProperty("Policy").GetValue(user,null); var current=(bool)policy.GetType().GetProperty("IsDisabled").GetValue(policy,null); if(current==disabled) return; policy.GetType().GetProperty("IsDisabled").SetValue(policy,disabled,null); manager.GetType().GetMethods().First(x=>x.Name=="UpdateUser"&&x.GetParameters().Length==1).Invoke(manager,new[] { user }); if(disabled) d.AutoDisabledUserIds.Add(id); else d.AutoDisabledUserIds.Remove(id); }
  public void EvaluateAutoDisable(IUserManager userManager) { var d=Read(); if(d.Fields.Any(x=>x.ControlsAccess&&x.Type==FieldType.Boolean)) return; var dateField=d.Fields.FirstOrDefault(x=>x.DisableUserOnDate&&!x.IsSeparator); var managed=d.AutoDisabledUserIds??new System.Collections.Generic.HashSet<string>(); var getUser=userManager.GetType().GetMethod("GetUserById",new[] { typeof(Guid) }); var updateUser=userManager.GetType().GetMethods().First(x=>x.Name=="UpdateUser"&&x.GetParameters().Length==1); foreach(var pair in d.Users) { var shouldDisable=false; if(dateField!=null&&pair.Value.Values.ContainsKey(dateField.Id)) { DateTime date; shouldDisable=DateTime.TryParse(pair.Value.Values[dateField.Id], out date)&&date.Date<=DateTime.Today; } Guid userId; if(!Guid.TryParse(pair.Key,out userId)) continue; var user=getUser.Invoke(userManager,new object[] { userId }); if(user==null) continue; var policy=user.GetType().GetProperty("Policy").GetValue(user,null); var disabled=(bool)policy.GetType().GetProperty("IsDisabled").GetValue(policy,null); if(shouldDisable&&!disabled) { policy.GetType().GetProperty("IsDisabled").SetValue(policy,true,null); updateUser.Invoke(userManager,new[] { user }); managed.Add(pair.Key); } else if(!shouldDisable&&managed.Contains(pair.Key)) { policy.GetType().GetProperty("IsDisabled").SetValue(policy,false,null); updateUser.Invoke(userManager,new[] { user }); managed.Remove(pair.Key); } } d.AutoDisabledUserIds=managed; Save(d); }
  public BackupDocument Export(string scope) { var d=Read(); return new BackupDocument { Scope=scope, Fields=d.Fields, Users=scope=="full" ? d.Users : null }; }
  public void Import(BackupDocument backup, string mode) { if(backup==null||backup.Fields==null) throw new ArgumentException("Invalid backup file"); if(mode!="replace"&&mode!="merge") throw new ArgumentException("Invalid import mode"); var current=Read(); var fields=backup.Fields.Where(x=>!string.IsNullOrWhiteSpace(x.Id)&&!string.IsNullOrWhiteSpace(x.Name)).GroupBy(x=>x.Id).Select(x=>x.First()).ToList(); if(mode=="replace") { current.Fields=fields; } else { foreach(var f in fields) { var existing=current.Fields.FirstOrDefault(x=>x.Id==f.Id); if(existing==null) current.Fields.Add(f); else { existing.Name=f.Name; existing.Type=f.Type; existing.Options=f.Options??new System.Collections.Generic.List<string>(); existing.IsActive=f.IsActive; existing.Order=f.Order; } } } if(backup.Scope=="full"&&backup.Users!=null) { if(mode=="replace") current.Users=backup.Users; else foreach(var item in backup.Users) current.Users[item.Key]=item.Value; } Save(current); }
  private static void Validate(FieldDefinition f,string v) { if(string.IsNullOrEmpty(v)) return; decimal n; DateTime dt; if(f.Type==FieldType.Number&&(!decimal.TryParse(v,System.Globalization.NumberStyles.Number,System.Globalization.CultureInfo.InvariantCulture,out n)||n<0||n>999999.99m)) throw new ArgumentException(f.Name+" must be a number between 0 and 999999.99"); if(f.Type==FieldType.Date&&!DateTime.TryParse(v,out dt)) throw new ArgumentException(f.Name+" must be a date"); if(f.Type==FieldType.Boolean&&v!="true"&&v!="false") throw new ArgumentException(f.Name+" must be true or false"); if(f.Type==FieldType.Select&&!f.Options.Contains(v)) throw new ArgumentException(f.Name+" has an invalid selection"); }
 }
}
